-- ROLLBACK for 20261006222000_m820_2_hints.sql — restores the pre-block descriptions (inventory snapshot 20261006).
BEGIN;
UPDATE fields x SET description = 'Legal name of Auftraggeber (Bauherr).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Municipality / utility / private / other.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'client_type';
UPDATE fields x SET description = 'Niedrig / Mittel / Hoch — scales project organisation and risk.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'complexity_level';
UPDATE fields x SET description = 'Mehrfachauswahl der beauftragten HOAI-Leistungsphasen (§1): LPH 0 Bedarfsplanung … LPH 9 Objektbetreuung.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'included_hoai_phases';
UPDATE fields x SET description = 'Wasserwirtschaft / Wasserbau / Abwasser / Abfall per §1 scope.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'primary_sector';
UPDATE fields x SET description = 'Neubau / Sanierung / Erweiterung / Optimierung / Konzept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_category';
UPDATE fields x SET description = 'Location description (Gemeinde, Landkreis, Bundesland, GPS if applicable).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_location';
UPDATE fields x SET description = 'Full project name as used in formal documents.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Short identifier for headers and tracking.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_name_short';
UPDATE fields x SET description = 'Unique project identifier assigned by client.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_number';
UPDATE fields x SET description = 'Klein / Mittel / Groß — drives downstream complexity scaling.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_size';
UPDATE fields x SET description = 'Explicit exclusions to avoid scope disputes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'scope_excluded';
UPDATE fields x SET description = 'Free-text description of technical scope boundaries.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'scope_technical';
UPDATE fields x SET description = 'Lifecycle state per worksheet_status enum (draft → final).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'worksheet_status';
UPDATE fields x SET description = 'Wer erbringt die Bedarfsplanung (LPH 0)? § 1 (PDF S. 14): „Teil 2 umfasst die Leistungserbringung aller Projektbeteiligten über alle Phasen hinweg, d. h. von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9), inklusive Inbetriebnahme und Übergabe an den Betrieb.“ und „Er erstreckt sich auch auf die zugehörigen Bedarfsplanungen, da sowohl die Konzepte als auch alle Projekte einer umfangreichen Vorbereitung durch den Auftraggeber bedürfen.“ Deshalb gibt es hier KEIN „entfällt“: jedes Konzept und jedes Projekt braucht eine Bedarfsplanung. Die Prüfungen von 820-2-11 (REQ-21, REQ-22, REQ-23) gelten unabhängig davon, wer die Phase erbringt.
[EN] Who performs needs planning (LPH 0)? § 1: "Part 2 covers the services of all parties across all phases, from needs planning (LPH 0) to object support (LPH 9) …" and "It also extends to the related needs planning, since concepts as well as all projects need extensive preparation by the client." Hence NO "does not occur" option: every concept and every project needs needs planning. The 820-2-11 checks apply whoever performs the phase.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'verantwortung_lph0';
UPDATE fields x SET description = 'Wer erbringt die Bauüberwachung (LPH 8)? § 4.1 (PDF S. 22): „Die örtliche Bauüberwachung und Bauoberleitung werden vergeben oder durch den Auftraggeber erbracht.“ § 1 (PDF S. 14): „Teil 2 umfasst die Leistungserbringung aller Projektbeteiligten über alle Phasen hinweg, d. h. von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9), inklusive Inbetriebnahme und Übergabe an den Betrieb.“ Auftragnehmer / Auftraggeber selbst / Dritter: REQ-19 (820-2-09) und REQ-43 (820-2-20) gelten in jedem Fall, auch wenn der Auftraggeber selbst überwacht (§ 5.6.2, PDF S. 54: „Werden Bauüberwachungsleistungen vom Auftraggeber selbst erbracht, sind die erforderlichen, fachlichen und personellen Ressourcen in ausreichendem Umfang bereitzustellen.“); REQ-44 nur bei einer Bauüberwachung durch einen Auftragnehmer oder Dritten (§ 5.6.3: „Wird in einem Projekt die Bauüberwachung durch einen Auftragnehmer wahrgenommen …“). „Entfällt“ nur, wenn das Projekt keine Bauausführung hat (§ 1: „Der Anwendungsbereich des vorliegenden Merkblatts umfasst alle Phasen der Konzepterstellung und Projektabwicklung bis hin zur Inbetriebnahme und Übergabe.“ — reine Konzepterstellung); dann sind die LPH-8-Prüfungen nicht erforderlich und ihre Eingaben ausgeblendet.
[EN] Who performs site supervision (LPH 8)? § 4.1: "Local site supervision and construction management are awarded or performed by the client."; § 1: "Part 2 covers the services of all parties across all phases …". Contractor / client himself / third party: REQ-19 and REQ-43 apply in every case, also when the client supervises himself (§ 5.6.2: the required technical and staff resources must then be provided); REQ-44 only for supervision by a contractor or third party (§ 5.6.3). "Does not occur" only when the project has no construction (§ 1: the scope covers "all phases of concept work and project execution" — concept work only); then the LPH 8 checks are not required and their inputs are hidden.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'verantwortung_lph8';
UPDATE fields x SET description = 'Wer ist für die Objektbetreuung / Gewährleistungsphase (LPH 9) verantwortlich? § 5.8.3 (PDF S. 64): „Es ist festgelegt, wer für die Phase LPH 9 verantwortlich ist.“ und „Es besteht auch die Möglichkeit, über einen Rahmenvertrag für mehrere Anlagen die Leistungen der LPH 9 auszuschreiben und zu beauftragen.“ Das gedruckte Problem ist gerade „Dem Auftragnehmer ist die LPH 9 nicht beauftragt worden.“ — deshalb gelten REQ-51, REQ-52 und REQ-52-2 (820-2-24) für jeden Verantwortlichen, auch für den Auftraggeber selbst. „Entfällt“ nur ohne Bauausführung (§ 1: „Der Anwendungsbereich des vorliegenden Merkblatts umfasst alle Phasen der Konzepterstellung und Projektabwicklung bis hin zur Inbetriebnahme und Übergabe.“); dann sind die Gewährleistungs-Prüfungen nicht erforderlich und die Gewährleistungsangaben ausgeblendet.
[EN] Who is responsible for object support / the warranty phase (LPH 9)? § 5.8.3: "It is laid down who is responsible for phase LPH 9." and "LPH 9 services can also be tendered and commissioned through a framework contract for several plants." The printed problem is exactly "The contractor was not commissioned with LPH 9." — so REQ-51, REQ-52 and REQ-52-2 apply to whoever is responsible, the client included. "Does not occur" only without construction (§ 1, concept work only); then the warranty checks are not required and the warranty entries hidden.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'verantwortung_lph9';
UPDATE compliance_requirements x SET description = 'Project falls within DWA-M 820-2 scope (Wasserwirtschaft, Wasserbau, Abwasser, Abfall) and covers LPH 0-9 phases as applicable.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.code = 'REQ-01';
UPDATE fields x SET description = 'Engineer''s confirmation that goals are stable for downstream design — addresses §5.3.3 (Zieldefinition unzureichend).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'goals_stability_signoff';
UPDATE fields x SET description = 'Operator party — relevant for §5.7 commissioning and handover.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'operator_betreiber';
UPDATE fields x SET description = 'Register der Projektziele (§2.1, DIN 18205 Tab. A.2): Kategorie (funktional/technisch, soziokulturell/gestalterisch, wirtschaftlich/terminlich, ökologisch) + Ziel + Anforderung.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'project_goals';
UPDATE fields x SET description = 'Project culture (collaboration, communication, decision binding, advisory function) explicitly addressed at project setup.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'projektkultur_documented';
UPDATE fields x SET description = 'Beteiligten-Register (§3, Bild 1): Beteiligter, Rolle, Verantwortung, Kommunikationsweg.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'stakeholders_list';
UPDATE compliance_requirements x SET description = 'All Beteiligte und Betroffene identified per §3 categories and Bild 1 communication relationships.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = 'Project goals defined per DIN 18205 Tab. A.2 categories; stability confirmed before downstream design.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.code = 'REQ-26';
UPDATE fields x SET description = 'Project-specific communication concept (internal + public) per Bild 1 and §5.3.5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'communication_concept';
UPDATE fields x SET description = 'Planning / construction / lots / framework contract type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'contract_type';
UPDATE fields x SET description = 'Whether HOAI fee structure is the basis of contract.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'hoai_compliance';
UPDATE fields x SET description = 'Whether VOB/A and VOB/B apply to construction lots.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'vob_applicable';
UPDATE fields x SET description = 'Register der Projektkorrespondenz (E-Mails, Briefe, Mitteilungen, Telefonate, Besprechungen): je Vorgang eine Zeile. Grundlage § 5.3.1: „Die Kommunikation muss regelmäßig, vorbereitet, effektiv und dokumentiert sein.“ und „Ergebnisse und Entscheidungen werden nicht ausreichend dokumentiert und die Umsetzung anschließend nicht nachverfolgt.“ (Problembeschreibung → Nachverfolgung); § 4.1: „Aufgabenverfolgung und Plandokumentation, Dokumentenmanagement sind notwendig.“. Nicht verpflichtend — ein Projekt darf noch keine Einträge haben.
[EN] Register of project correspondence (emails, letters, notifications, calls, meetings), one row per item. Basis § 5.3.1: "Communication must be regular, prepared, effective and documented." and the printed problem "results and decisions are not documented sufficiently and their implementation is not followed up"; § 4.1: "task tracking, plan documentation and document management are necessary". Not required — a project may have no entries yet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'korrespondenz';
UPDATE fields x SET description = 'Ausgabe der Gleichung 820-2-03-D1 (count_rows(korrespondenz)). Anzahl der vollständigen Zeilen des Korrespondenz-Registers (Datum, Richtung, Betreff ausgefüllt). [EN] Number of complete correspondence rows (date, direction, subject filled).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'korrespondenz_count';
UPDATE fields x SET description = 'Ausgabe der Gleichung 820-2-03-D2 (count_rows(korrespondenz, nachverfolgung_noetig == true AND erledigt == false)). Anzahl der Korrespondenz-Zeilen mit „Nachverfolgung nötig“ und nicht „erledigt“ („… die Umsetzung anschließend nicht nachverfolgt“, § 5.3.1). Kein Gate. [EN] Rows with follow-up needed and not done; no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'korrespondenz_nachverfolgung_offen';
UPDATE equations x SET description = 'Anzahl der vollständigen Zeilen des Korrespondenz-Registers (Datum, Richtung, Betreff ausgefüllt). [EN] Number of complete correspondence rows (date, direction, subject filled).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.equation_number = '820-2-03-D1';
UPDATE equations x SET description = 'Anzahl der Korrespondenz-Zeilen mit „Nachverfolgung nötig“ und nicht „erledigt“ („… die Umsetzung anschließend nicht nachverfolgt“, § 5.3.1). Kein Gate. [EN] Rows with follow-up needed and not done; no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.equation_number = '820-2-03-D2';
UPDATE fields x SET description = 'Register geltender DIN-Normen (§6.2): Norm + Titel + Geltungsbereich.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'applicable_din_standards';
UPDATE fields x SET description = 'Register geltender DWA-/ATV-Regelwerke (§6.2): Regelwerk + Titel + Geltungsbereich.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'applicable_dwa_standards';
UPDATE fields x SET description = 'Register der Auftraggeber-Richtlinien (§6.1/§6.2): Richtlinie + Beschreibung.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'client_guidelines';
UPDATE fields x SET description = 'All cited regulations are current edition — addresses §6.3.2 (Regelwerke sind veraltet).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'regulations_current_check';
UPDATE compliance_requirements x SET description = 'Cited regulations / Regelwerke are current edition; outdated entries identified and flagged.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.code = 'REQ-53';
UPDATE fields x SET description = 'Non-delegable Bauherr tasks documented (scope, automation, redundancy, operational requirements, quality) — addresses §4.3.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'bauherr_tasks_defined';
UPDATE fields x SET description = 'Decision authority, value thresholds, escalation paths documented — addresses §4.3.3 and §4.3.4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'decision_competencies_mapped';
UPDATE fields x SET description = 'Mutual expectations among all parties actively managed — covers Erwartungsmanagement and Beziehungsmanagement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'expectations_management_active';
UPDATE fields x SET description = 'Execute phase: Leistungserbringung aller Projektbeteiligten — Auftraggeber, Auftragnehmer, Gutachter, ausführende Firmen.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'mgmt_cycle_durchfuehren';
UPDATE fields x SET description = 'Cadence at which the Plan-Do-Check-Steer cycle is iterated. Regulation specifies 2-4 weeks as typical.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'mgmt_cycle_frequency';
UPDATE fields x SET description = 'Plan phase of the Management-Regelkreis: realistic, robust plan with cost target (per DIN 276), schedule target (Fertigstellungstermin), and fortschreibung when needed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'mgmt_cycle_planen';
UPDATE fields x SET description = 'Handbook follows Anhang B structure — addresses §4.3.5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'project_handbook_complete';
UPDATE fields x SET description = 'Projektleitung embedded as line function in the project organigram (distinct from Projektsteuerung as Stabsstelle).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'project_leadership_function';
UPDATE fields x SET description = 'Mehrfachauswahl der Handlungsbereiche der Projektsteuerung (§4.1, §4.3–4.7): Projektorganisation, Termin-, Kosten-, Vertrags-, Qualitäts-, Risikomanagement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektsteuerung_scope';
UPDATE fields x SET description = 'Plan 3: Mehrfachauswahl über die acht gedruckten Kapitel des Anhangs B (Tabelle ANHANGB, Gliederungsvorschlag — anhaltswert) neben dem Boolean project_handbook_complete (gelesen von REQ-07, konsumiert von 820-2-06 / -15); ein Gate "alle acht Kapitel angekreuzt" ist STAGED (m820_2-G-8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projekthandbuch_kapitel';
UPDATE fields x SET description = 'Register der Projektschritte: je Schritt Datum, Schritt, Verantwortlich, Ergebnis, Nachweis, Status. Grundlage § 4.1: „Aufgabenverfolgung und Plandokumentation, Dokumentenmanagement sind notwendig.“ und „Reihenfolge der Vorgehensweise beschreiben, d. h. die Prozesse müssen geplant werden.“; § 4.3.6: „Darüber hinaus sind wichtige, bis zum nächsten Bericht geplante Arbeitsschritte, Korrekturmaßnahmen, Maßnahmen der Risikoverfolgung und Arbeitssicherheit enthalten.“ (geplante Arbeitsschritte). Nicht verpflichtend.
[EN] Register of project steps: date, step, responsible, result, evidence, status. Basis § 4.1 "task tracking … necessary", "the processes must be planned"; § 4.3.6 status reports contain the "work steps planned until the next report". Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektschritte';
UPDATE fields x SET description = 'Ausgabe der Gleichung 820-2-05-D1 (count_rows(projektschritte)). Anzahl der vollständigen Zeilen des Registers Projektschritte (Schritt und Status ausgefüllt). [EN] Number of complete project-step rows.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektschritte_count';
UPDATE fields x SET description = 'Ausgabe der Gleichung 820-2-05-D2 (count_rows(projektschritte, status != ''erledigt'')). Anzahl der Schritte mit Status geplant oder in Arbeit. Kein Gate. [EN] Steps planned or in progress; no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektschritte_offen';
UPDATE fields x SET description = '§ 4.3.4 (PDF S. 26): „Bereits in der Phase der Konzeption und Bedarfsplanung wird der Betrieb aktiv eingebunden.“ Gelesen von REQ-06 (Warnung). Nicht verpflichtend.
[EN] § 4.3.4: "The operator is actively involved already in the concept and needs-planning phase." Read by REQ-06 (warning). Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'betrieb_frueh_eingebunden';
UPDATE equations x SET description = 'Anzahl der vollständigen Zeilen des Registers Projektschritte (Schritt und Status ausgefüllt). [EN] Number of complete project-step rows.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.equation_number = '820-2-05-D1';
