UPDATE fields x SET description = 'Plan 3: Treiber für REQ-59 ("BIM basics established (if applicable)", heute leere Bedingung auf 820-2-25) — Vorschlag IF bim_methode_angewendet == true THEN bim_basics_established == true auf -27 STAGED (m820_2-G-5); die übrigen Felder von -27 / -28 sind nicht BIM-bedingt (m820_2-J-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.symbol = 'bim_methode_angewendet';
UPDATE compliance_requirements x SET description = 'Software products, hardware, and digital infrastructure adequate for project.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.code = 'REQ-57';
UPDATE compliance_requirements x SET description = 'Data quality verified per §2.1 criteria (Vollständigkeit, Eindeutigkeit, Korrektheit, Aktualität, Genauigkeit).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.code = 'REQ-58';
UPDATE compliance_requirements x SET description = '§ 8.3.2 (PDF S. 79): „Es wird geklärt, ob das Projekt für die Anwendung der BIM-Methodik geeignet ist und ob die Beteiligten sowohl beim Auftraggeber als auch bei den Auftragnehmern die nötigen Kompetenzen und Qualifikationen aufweisen.“ „Das erforderliche Know-how und die Ressourcen werden geschaffen, um die Methode anwenden zu können.“ Nur wenn das Projekt mit der BIM-Methode abgewickelt wird: BIM-Grundlagen vorhanden. Vorher leere Bedingung auf 820-2-25.
[EN] § 8.3.2: "It is clarified whether the project suits the BIM method and whether the parties on the client and contractor side have the necessary competences and qualifications." "The required know-how and resources are created to be able to apply the method." Only when the project runs with BIM: BIM basics established. Was an empty condition on 820-2-25.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.code = 'REQ-59';
UPDATE fields x SET description = 'Register technischer/organisatorischer Maßnahmen — TOM (§8.8, DSGVO/BSI): Art (technisch/organisatorisch) + Maßnahme.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.symbol = 'data_security_measures';
UPDATE fields x SET description = 'Rights at digital models and data (Urheber-, Verwertungsrechte) clarified — §8.9.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.symbol = 'digital_rights_clarified';
UPDATE fields x SET description = 'GIS data quality assessment per §8.7.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.symbol = 'gis_data_quality';
UPDATE compliance_requirements x SET description = 'TOM (technische und organisatorische Maßnahmen) per DSGVO/BSI; digital data rights clarified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.code = 'REQ-60';
COMMIT;
